/*
 * The design tokens for Katalyst.
 *
 * This file is the whole visual vocabulary of the product in one place: every
 * colour, size, weight, space and duration the interface is allowed to use.
 * Nothing else in the app writes a raw colour or a raw pixel number. Later work
 * — the workbench canvas with its proposition tiles and causal wires — inherits
 * these same names, so the first screen and the finished product cannot drift
 * apart visually.
 *
 * Which product rules this serves (from PRODUCT_REQUIREMENTS.md section 7):
 *
 *   UX-6  "Colour is law."  Direction of financial effect is blue for up and
 *         amber for down, never red and green, and always carried by a glyph
 *         and a word as well as a hue. Tail risk (a rare, large outcome) is a
 *         hatched texture rather than a colour, because texture survives every
 *         kind of colour blindness and survives inverting light and dark.
 *   UX-7  "Motion budget."  On this screen there is exactly one animation: a
 *         placeholder fading into the value that replaced it. One duration
 *         token controls it, and it becomes instant when the operating system
 *         asks for reduced motion.
 *   UX-11 "Typography."  One interface typeface, one monospace typeface with
 *         fixed-width digits for every number, exactly three sizes and exactly
 *         three weights. Hierarchy comes from colour and spacing, not size.
 *   UX-12 "Themes and access."  Dark is the default; a light theme is defined
 *         too. Every piece of text clears a contrast ratio of 4.5 to 1 against
 *         the surface behind it, in both themes. The ratios are written beside
 *         each colour below.
 *
 * How the two themes are chosen:
 *   - The page ships dark, because `index.html` sets `data-theme="dark"` on the
 *     html element. That attribute wins over everything else.
 *   - `data-theme="light"` forces the light theme.
 *   - Remove the attribute and the page follows the operating system: dark
 *     unless the operating system asks for light.
 */

:root {
  /* ---- Typefaces ------------------------------------------------------ *
   * Inter for the interface and JetBrains Mono for every number.
   *
   * Why this pair, and not Geist: both are shipped as ordinary npm packages
   * (`@fontsource-variable/...`) that carry the font files themselves, so the
   * app draws its first frame with no request to any outside service and works
   * with no network at all inside a container. The `geist` package publishes
   * its fonts only through the Next.js font loader, which this app does not
   * use. Inter is a neutral interface face that stays legible at 13 pixels;
   * JetBrains Mono has fixed-width digits, so a number that changes does not
   * make the column beside it jump sideways.
   *
   * The system fallbacks after each name are what a browser draws in the
   * fraction of a second before the font file arrives. */
  --font-interface:
    "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono Variable", ui-monospace, "SF Mono", "Cascadia Mono", monospace;

  /* ---- Type scale: exactly three sizes, exactly three weights --------- *
   * 13 / 15 / 22 pixels. A fourth size is not a small addition; it is a new
   * rule everything afterwards has to obey, so there are three. */
  --text-sm: 13px;
  --text-md: 15px;
  --text-lg: 22px;

  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;

  /* ---- Spacing: an eight-pixel grid ----------------------------------- *
   * Every margin, padding and gap is one of these. `--space-hair` is the one
   * half-step, for the gap between a glyph and the word beside it. */
  --space-hair: 4px;
  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 48px;
  --space-6: 64px;

  --radius: 6px;

  /* ---- Motion --------------------------------------------------------- *
   * One duration, used only for opacity. Nothing here moves position, scales,
   * bounces or loops. */
  --duration-fast: 120ms;

  /* ---- Dark theme: the default ---------------------------------------- *
   * Contrast ratios below are measured against `--surface` (#0E1116), whose
   * own ratio against white is 18.9 to 1. It is a very dark blue-grey rather
   * than pure black: pure black against bright text vibrates at small sizes,
   * and leaves no darker shade to fall back on. */
  color-scheme: dark;

  --surface: #0e1116;
  /* The page behind everything. */
  --surface-raised: #151a21;
  /* A panel sitting on the page: lighter, no shadow. */
  --hairline: rgb(233 237 243 / 10%);
  /* A one-pixel border at 10% of the text colour. Separation without chrome. */

  --text: #e9edf3;
  /* 16.1 to 1 on --surface, 14.9 to 1 on --surface-raised. */
  --text-muted: #98a2b1;
  /* 7.3 to 1 on --surface, 6.8 to 1 on --surface-raised. Quiet, still readable. */

  --accent: #5fd4c4;
  /* 10.5 to 1 on --surface. A teal used sparingly — a state glyph, the mark in
   * the icon. Deliberately not the same hue as --dir-up, so that "this is fine"
   * can never be mistaken for "this moves the position up". */

  --dir-up: #6fb3ff;
  /* 8.6 to 1 on --surface. Financial effect upward. Always drawn with an
   * upward glyph and a sign as well (UX-6, and invariant INV-12). */
  --dir-down: #f0b23c;
  /* 10.0 to 1 on --surface. Financial effect downward. Blue and amber, never
   * red and green: red-green fails the most common form of colour blindness,
   * and carries loss-and-gain baggage that is wrong half the time. */

  --tail: repeating-linear-gradient(
    45deg,
    rgb(233 237 243 / 0%) 0 3px,
    rgb(233 237 243 / 28%) 3px 4px
  );
  /* Tail risk — a rare outcome large enough to matter — is marked with this
   * diagonal hatch, never with a colour. A texture is still a texture in
   * greyscale, in a screenshot, and to a colour-blind reader. */

  --focus: #7ce0d0;
  /* The ring drawn around whatever the keyboard is on. Bright enough to find at
   * a glance: 12.1 to 1 on --surface, far above the 3 to 1 a non-text mark
   * needs. */

  /* ==== THE COLOUR LAW: ADDED FOR THE WIRES AND THE PANEL ================ *
   * Everything from here to the end of this block is new. No value above it
   * changed.
   *
   * The organising rule is **one channel per meaning**. A channel is one thing
   * the eye can vary on its own — brightness, hue, texture, stroke pattern,
   * stroke width, shape, position. Six meanings, six channels, and no channel
   * doing two jobs, because every failure in this area is two meanings
   * fighting over one channel.
   *
   *   how likely a claim is  -> brightness, the five-step ramp below
   *   which way money moves   -> hue, --dir-up and --dir-down above, never alone
   *   tail risk               -> texture, --tail above
   *   what kind of push       -> the wire's stroke: pattern, width, doubling
   *   where an arrow came from-> a mark of one, two or three dots at its tail
   *   which branch you are in -> the four branch hues below, plus a name chip
   *
   * Only the first and the last are colours defined here. The stroke and the
   * mark are deliberately colourless: every wire is drawn in --text-muted, and
   * a wire's hue says nothing at all. */

  /* ---- How likely a claim is: a five-step neutral ramp ----------------- *
   * Five brightnesses of the same blue-grey as the surface. Neutral on
   * purpose: any hue in here would be a second voice in the channel that means
   * "which way the money moves".
   *
   *   --p-0  0 to under .2      --p-3  .6 to under .8
   *   --p-1  .2 to under .4     --p-4  .8 to 1
   *   --p-2  .4 to under .6
   *
   * Three rules on it. It never carries text — a number is always drawn in
   * --text, so it always clears 4.5 to 1, while the ramp paints a bar, which
   * is a graphic and needs 3 to 1. It never paints a whole tile, because
   * tile-wide brightness is already spent on the old world in a diff and on
   * the hover lens. And five steps are a glance, never a reading: the exact
   * number and its range are printed beside the bar every time.
   *
   * Ratios below are measured against --surface-raised, the panel a bar is
   * drawn on, and then against --surface. The lowest step clears 3 to 1, so
   * even a bar for an unlikely claim is a bar somebody can see. */
  --p-0: #646a73;
  /* 3.2 to 1 on --surface-raised, 3.5 to 1 on --surface. */
  --p-1: #7f858e;
  /* 4.7 to 1 on --surface-raised, 5.1 to 1 on --surface. */
  --p-2: #9ba1a9;
  /* 6.7 to 1 on --surface-raised, 7.3 to 1 on --surface. */
  --p-3: #b9bdc5;
  /* 9.3 to 1 on --surface-raised, 10.0 to 1 on --surface. */
  --p-4: #d5dae0;
  /* 12.4 to 1 on --surface-raised, 13.4 to 1 on --surface. */

  /* ---- What kind of push an arrow is: the four stroke widths ----------- *
   * Width comes from the size of a push regardless of its sign. Four steps,
   * not a continuous ramp, because a fifth is not tellable apart at a
   * hairline. Which step a push lands in is a comparison against three
   * thresholds — a lookup, not arithmetic — and the thresholds are written
   * down in `graph/wires/encodings.ts` beside the words they pair with. */
  --wire-1: 1px;
  --wire-2: 2px;
  --wire-3: 3px;
  --wire-4: 4px;
  /* The clear gap down the middle of a wire that has to keep holding. A
   * `sustain` wire is drawn as two parallel strokes with this between them; a
   * `trigger` wire is a single stroke. */
  --wire-gap: 2px;

  /* ---- Which branch you are in ---------------------------------------- *
   * Four hues, used only on a branch's lane and its chips and never on a
   * tile's meaning. Every branch also carries a name chip with its label, so a
   * branch is readable with no colour at all.
   *
   * **Not amber.** Amber already means "the money moves down", and one hue
   * cannot mean two things.
   *
   * Nothing in this build draws a branch — the branch panel is the next piece
   * of work — so these four are defined and unused. They are written now so
   * that nobody borrows a direction hue for a lane in the meantime.
   *
   * The teal is deliberately darker and bluer than --accent and --focus, which
   * are also teals. See the note in `styles/__tests__/colourLaw.test.ts`. */
  --branch-violet: #b193f2;
  /* 7.5 to 1 on --surface, 6.9 to 1 on --surface-raised. */
  --branch-teal: #2f93b0;
  /* 5.3 to 1 on --surface, 4.9 to 1 on --surface-raised. */
  --branch-rose: #f18aa6;
  /* 8.0 to 1 on --surface, 7.4 to 1 on --surface-raised. */
  --branch-slate: #98a8c2;
  /* 7.8 to 1 on --surface, 7.3 to 1 on --surface-raised. */

  /* ---- Two more durations --------------------------------------------- *
   * The motion budget is three moves and no more: wires drawing in causal
   * order, a branch arriving, and a likelihood rolling from its old figure to
   * its new one. Everything else is an opacity change of at most
   * --duration-fast.
   *
   * Nothing in this build spends either of these yet — no wire draws itself in
   * and no number moves. They are named here because the ordering below, under
   * reduced motion, is a rule about them: the tweening goes and the ordering
   * stays, because the ordering is the causality. */
  --duration-wave: 200ms;
  --duration-stagger: 60ms;
}

/* Light theme, forced by the html element's data-theme attribute. */
[data-theme="light"] {
  color-scheme: light;

  --surface: #f7f8fa;
  --surface-raised: #ffffff;
  --hairline: rgb(16 20 26 / 10%);

  --text: #10141a;
  /* 17.4 to 1 on --surface, 18.5 to 1 on --surface-raised. */
  --text-muted: #5b6577;
  /* 5.5 to 1 on --surface, 5.9 to 1 on --surface-raised. */

  --accent: #0f766e;
  /* 5.2 to 1 on --surface, 5.5 to 1 on --surface-raised. */

  --dir-up: #1f5fcc;
  /* 5.5 to 1 on --surface, 5.9 to 1 on --surface-raised. */
  --dir-down: #96590a;
  /* 5.3 to 1 on --surface, 5.6 to 1 on --surface-raised. Amber has to go dark
   * and slightly brown on a white page to clear 4.5 to 1; the glyph and the
   * word carry the meaning either way. */

  --tail: repeating-linear-gradient(45deg, rgb(16 20 26 / 0%) 0 3px, rgb(16 20 26 / 24%) 3px 4px);

  --focus: #0d6e66;
  /* 5.7 to 1 on --surface. */

  /* ==== THE COLOUR LAW, IN LIGHT ========================================= *
   * The ramp runs the other way here, and that is the point rather than an
   * oversight. On a near-black page a more likely claim is a brighter bar; on
   * a white page a brighter bar would be a bar you cannot see. What is
   * constant in both themes is what the eye actually reads: **more likely is
   * more contrast against the page.** So the light ramp goes from the faintest
   * step a reader can still see up to nearly the text colour.
   *
   * Every step clears 3 to 1 against both surfaces, which is what a bar — a
   * graphic rather than a word — has to clear. */
  --p-0: #868c97;
  /* 3.2 to 1 on --surface, 3.4 to 1 on --surface-raised. */
  --p-1: #6e747f;
  /* 4.4 to 1 on --surface, 4.7 to 1 on --surface-raised. */
  --p-2: #565c66;
  /* 6.3 to 1 on --surface, 6.7 to 1 on --surface-raised. */
  --p-3: #414851;
  /* 8.7 to 1 on --surface, 9.2 to 1 on --surface-raised. */
  --p-4: #2e353e;
  /* 11.7 to 1 on --surface, 12.4 to 1 on --surface-raised. */

  --branch-violet: #6338c4;
  /* 6.8 to 1 on --surface, 7.3 to 1 on --surface-raised. */
  --branch-teal: #0a5a72;
  /* 7.2 to 1 on --surface, 7.7 to 1 on --surface-raised. */
  --branch-rose: #a32f52;
  /* 6.4 to 1 on --surface, 6.8 to 1 on --surface-raised. */
  --branch-slate: #44527a;
  /* 7.2 to 1 on --surface, 7.7 to 1 on --surface-raised. */
}

/* No data-theme attribute at all: follow the operating system. Dark stays the
 * default, because only an explicit request for light lands here. */
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    color-scheme: light;

    --surface: #f7f8fa;
    --surface-raised: #ffffff;
    --hairline: rgb(16 20 26 / 10%);

    --text: #10141a;
    --text-muted: #5b6577;

    --accent: #0f766e;

    --dir-up: #1f5fcc;
    --dir-down: #96590a;

    --tail: repeating-linear-gradient(45deg, rgb(16 20 26 / 0%) 0 3px, rgb(16 20 26 / 24%) 3px 4px);

    --focus: #0d6e66;

    /* The colour law in light, repeated here for the reader who has asked for
     * no theme at all and whose operating system asks for a light page. Same
     * values as the forced light theme above, and the same reason: more likely
     * is more contrast against the page. */
    --p-0: #868c97;
    --p-1: #6e747f;
    --p-2: #565c66;
    --p-3: #414851;
    --p-4: #2e353e;

    --branch-violet: #6338c4;
    --branch-teal: #0a5a72;
    --branch-rose: #a32f52;
    --branch-slate: #44527a;
  }
}

/* When the operating system asks for less movement, the tweening goes and the
 * ordering stays (UX-7).
 *
 * *Tweening* is the in-between frames that make a change look like a movement.
 * Those go: a value still replaces the placeholder, and a wire still arrives,
 * but neither takes any time doing it. What does **not** go is
 * `--duration-stagger`, the gap between one layer of the map and the next,
 * because that gap is the order the argument runs in — the ordering is the
 * causality, and removing it would remove the one thing the movement was for. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 0ms;
    --duration-wave: 0ms;
  }
}

/**
 * How big a tile is, and how far the map may be zoomed.
 *
 * The automatic layout has to know how big every tile is *before* the browser
 * has drawn one — it works out where the tiles go from the shape of the map
 * alone, and it cannot wait for measurements. So a tile's height is computed
 * here, from the claim's own content, by a plain function of plain data. That
 * keeps the layout a pure function of the map: the same map lays out the same
 * way every time, and the layout can be tested without a browser.
 *
 * The block heights below were measured once in the browser against the stored
 * example and are written down rather than read back at run time. If the tile's
 * stylesheet changes a line height or a gap, these change with it — and the
 * check for that is visual: a tile whose numbers are wrong has a gap at the
 * bottom or loses its last line.
 */

import type { ClaimView } from "../world";

/** How wide a tile is. Settled: 280 pixels, and measurable on any screenshot. */
export const TILE_WIDTH = 280;

/**
 * How tall a tile may be, at the least and at the most.
 *
 * "Clamped height" is a floor and a ceiling with the content deciding in
 * between — not one height for every tile. The floor is what a tile holding
 * only a heading, a one-line claim and the three belief chips comes to; the
 * ceiling is what the densest tile in the stored example needs, which is the
 * hypothesis, with a three-line claim, a reason and two evidence clippings.
 * Both are on the eight-pixel grid.
 */
export const TILE_MIN_HEIGHT = 152;
/**
 * The ceiling was 272, which was what the densest tile in the stored example
 * needed **before a tile could carry badges**. A claim the reader supposed and a
 * later edit pushed back down says so on its own face, in one line that names
 * the edit responsible — *Supposed · Oct 1 → Retracted · Oct 2 · by "a confirmed
 * military strike on Iranian territory"* — and that line is three lines wide on
 * a 280-pixel tile. A ceiling that cut it off would hide the one thing the tile
 * is there to say.
 */
export const TILE_MAX_HEIGHT = 320;

/* ---- The blocks a tile is made of, in pixels --------------------------- *
 * Measured in the browser, at the type sizes and line heights `tile.css`
 * sets. Every one of them is a height the browser actually produced. */

/** Top and bottom padding together: twelve pixels each. */
const PADDING = 24;

/** The gap between one block and the next. */
const GAP = 8;

/** The heading row: what kind of claim this is, and when it settles. */
const HEADER = 21;

/**
 * One line of the claim, at fifteen pixels over a line height of 1.35.
 *
 * Rounded up wherever it is used, never down: a line that is given a quarter of
 * a pixel less than it needs loses the bottom of its descenders.
 */
const CLAIM_LINE = 20.25;

/**
 * The three belief chips: owner, number and range, with the rule above them.
 *
 * Measured at 69 in the browser, which is two pixels more than the 67 written
 * here before the chips grew their brightness bars. A row that is two pixels
 * short takes them off the bottom of the tile.
 */
const BELIEF_RAIL = 69;

/**
 * The line a dead end prints saying why nothing here can be traded. Clamped to
 * two lines, and the only reason any tile prints for itself.
 */
const FINDING = 35;

/** One evidence clipping, and the gap between two of them. */
const CLIPPING = 21;
const CLIPPING_GAP = 4;

/**
 * One line of a claim's badges, and the hairline and padding the badges
 * themselves add to the block once.
 *
 * Thirteen pixels over a line height of 1.35 is 17.5, and each badge is drawn
 * with a hairline round it and a pixel of padding, which lifts a line box to
 * about 19. Both measured in the browser against the stored example's strike
 * branch, where the tallest badge line in the product — *Supposed · Oct 1 →
 * Retracted · Oct 2 · by "…"* — runs to three lines.
 */
const BADGE_LINE = 19;
const BADGE_PADDING = 4;

/**
 * Roughly how many characters of a badge fit on one line.
 *
 * The badges flow across the same 256 pixels the claim wraps in, set at thirteen
 * pixels in the interface face, whose average character is about six and a half
 * pixels wide — so about thirty-eight. An estimate, and safe to be one for the
 * same reason the claim's is: the same number decides both how tall the tile is
 * and how much room the badges get, so the two cannot disagree.
 */
const BADGE_CHARACTERS_PER_LINE = 38;

/** The separator drawn between one badge and the next, counted into the width. */
const BADGE_SEPARATOR = " → ";

/**
 * Roughly how many characters of the claim fit on one line.
 *
 * The claim has 256 pixels to wrap in (244 on the two tiles whose outline cuts
 * into one side) and is set at fifteen pixels in the interface face, whose
 * average character is about eight pixels wide — so about thirty-three.
 *
 * It is an estimate, and it is safe to be one because the same number decides
 * both how tall the tile is and how many lines the claim is allowed to show.
 * The two cannot disagree: if the estimate is generous the tile has a little
 * room to spare, and if it is mean the claim stops one line earlier than it
 * might have. Neither case can push a word out of the box.
 */
const CLAIM_CHARACTERS_PER_LINE = 33;

/** The most lines of the claim a tile ever shows. The rest lives in the panel. */
const CLAIM_MAX_LINES = 3;

/**
 * How many lines of the claim this tile shows.
 *
 * @param claim The claim, in the words the map serves it in.
 */
export function claimLines(claim: string): number {
  const wanted = Math.ceil(claim.length / CLAIM_CHARACTERS_PER_LINE);
  return Math.min(CLAIM_MAX_LINES, Math.max(1, wanted));
}

/**
 * How many lines this claim's badges take.
 *
 * Zero when it has none, which is every claim on a map nobody has edited.
 *
 * @param claim The claim the tile is for.
 */
export function badgeLines(claim: ClaimView): number {
  const badges = claim.badges ?? [];
  if (badges.length === 0) {
    return 0;
  }
  const characters =
    badges.reduce((sum, badge) => sum + badge.words.length, 0) +
    BADGE_SEPARATOR.length * (badges.length - 1);
  return Math.max(1, Math.ceil(characters / BADGE_CHARACTERS_PER_LINE));
}

/** Round up to the eight-pixel grid the whole interface sits on. */
function toGrid(height: number): number {
  return Math.ceil(height / 8) * 8;
}

/**
 * How tall this claim's tile is: as tall as its own content, on the grid, and
 * inside the floor and the ceiling.
 *
 * @param claim The claim the tile is for.
 */
export function tileHeight(claim: ClaimView): number {
  const blocks: number[] = [HEADER, Math.ceil(CLAIM_LINE * claimLines(claim.claim)), BELIEF_RAIL];

  // The foot of the tile: the reason a slot has no number, and the evidence
  // clippings. It is only there when there is something to put in it — and
  // when the badges arrive, having one of those will put it there too.
  const foot: number[] = [];
  if (claim.kind === "not_tradeable" && claim.beliefs.market.absence !== undefined) {
    foot.push(FINDING);
  }
  const clippings = claim.evidence.length;
  if (clippings > 0) {
    foot.push(CLIPPING * clippings + CLIPPING_GAP * (clippings - 1));
  }
  const badges = badgeLines(claim);
  if (badges > 0) {
    foot.push(BADGE_LINE * badges + BADGE_PADDING);
  }
  if (foot.length > 0) {
    blocks.push(foot.reduce((a, b) => a + b, 0) + GAP * (foot.length - 1));
  }

  const natural = PADDING + blocks.reduce((a, b) => a + b, 0) + GAP * (blocks.length - 1);
  return Math.min(TILE_MAX_HEIGHT, Math.max(TILE_MIN_HEIGHT, toGrid(natural)));
}

/* ---- Zoom --------------------------------------------------------------- */

/**
 * The smallest a word may be drawn on the reader's screen, in pixels.
 *
 * This is the rule the two zoom numbers below are worked out from, rather than
 * a number chosen for how it looked.
 */
const SMALLEST_READABLE_TEXT = 11;

/** The smallest and largest of the three type sizes, as `tokens.css` sets them. */
const SMALLEST_TEXT = 13;
const LARGEST_TEXT = 22;

/**
 * Below this zoom a tile stops showing everything and shows a summary instead.
 *
 * **This was 0.6, and it is now eleven over thirteen — about 0.85.** The plan
 * settled on 0.6 before the type scale was settled, and the two turned out not
 * to fit together: a full tile's smallest words are thirteen pixels, so at 0.6
 * zoom they arrive on the glass at under eight, which breaks the rule that
 * nothing is ever drawn below eleven. Eleven over thirteen is the exact zoom at
 * which thirteen-pixel type lands at eleven pixels, so a full tile is only ever
 * shown at or above it, and below it the summary takes over — which sets every
 * word in the largest size and so clears the floor all the way down.
 */
export const SUMMARY_BELOW_ZOOM = SMALLEST_READABLE_TEXT / SMALLEST_TEXT;

/**
 * How far out the map may be zoomed.
 *
 * The summary sets every word it draws in the largest of the three type sizes,
 * so the floor is the one zoom at which that size arrives at eleven pixels:
 * eleven over twenty-two, which is a half.
 */
export const SMALLEST_ZOOM = SMALLEST_READABLE_TEXT / LARGEST_TEXT;

/** How far in the map may be zoomed. Past this a tile is merely large. */
export const LARGEST_ZOOM = 1.4;

/**
 * The smallest type size a tile draws at this zoom, in pixels, before the map's
 * own scaling is applied.
 *
 * Multiply it by the zoom and you have what lands on the reader's screen, which
 * is what `layout.test.ts` checks never falls below eleven.
 *
 * @param zoom How far the map is zoomed in, where 1 is life size.
 */
export function smallestTextAt(zoom: number): number {
  return zoom < SUMMARY_BELOW_ZOOM ? LARGEST_TEXT : SMALLEST_TEXT;
}

/** The smallest a word is ever drawn on the reader's screen, in pixels. */
export const TEXT_FLOOR = SMALLEST_READABLE_TEXT;

/* ---- The first frame ----------------------------------------------------- */

/** A rectangle in the map's own coordinates. */
export interface Box {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** How far the map is moved and zoomed to put something in front of the reader. */
export interface Frame {
  /** How far in the map is zoomed, where 1 is life size. */
  readonly zoom: number;
  /** How far the map is slid sideways, in screen pixels. */
  readonly x: number;
  /** How far the map is slid up or down, in screen pixels. */
  readonly y: number;
}

/** The breathing room left around the map when it is framed, as a share of its size. */
const FIRST_FRAME_MARGIN = 0.04;

/** The gap left at the edge when the map is too big to fit and has to be panned. */
const EDGE_GAP = 16;

/**
 * How the map is framed the first time it is drawn — and the one promise that
 * framing makes: **the first frame never shows summary tiles.**
 *
 * The obvious rule is "fit the whole map". On a wide screen with the panel beside
 * it that lands at about 0.8 zoom on the stored example, which is under the zoom
 * at which a full tile's smallest words would be drawn below eleven pixels — so
 * every tile would open as a summary, and the reader's first sight of the
 * product would be seven boxes with a headline and three numbers in them.
 *
 * So the rule has a floor, and the floor is the same eleven-pixel rule
 * everything else here is derived from: frame the whole map if it fits at a
 * readable size, and if it does not, keep the readable size and start at the
 * map's beginning, on the left, where the hypothesis is. The reader pans to the
 * rest. A tile changes representation rather than shrinking; the same principle,
 * applied to the frame rather than to the tile.
 *
 * @param map Everything the frame has to hold, in the map's own coordinates.
 * @param canvas How much room there is for it, in screen pixels.
 */
export function firstFrame(map: Box, canvas: { width: number; height: number }): Frame {
  const fits = Math.min(
    canvas.width / (map.width * (1 + FIRST_FRAME_MARGIN)),
    canvas.height / (map.height * (1 + FIRST_FRAME_MARGIN)),
  );
  // Never blown up past life size, however small the map; never shrunk past the
  // point where a full tile would have to become a summary.
  const zoom = Math.max(SUMMARY_BELOW_ZOOM, Math.min(1, fits));
  const place = (room: number, start: number, size: number): number => {
    const shown = size * zoom;
    return shown <= room ? (room - shown) / 2 - start * zoom : EDGE_GAP - start * zoom;
  };
  return {
    zoom,
    x: place(canvas.width, map.x, map.width),
    y: place(canvas.height, map.y, map.height),
  };
}

/** How many tiles a single layer may show before the rest are collapsed into one. */
export const TILES_PER_LAYER = 7;

/**
 * What the canvas draws, written by hand rather than generated.
 *
 * This is the browser's own view of one world — a map with its numbers filled
 * in — and it is deliberately **not** taken from `src/api/schema.ts`. That file
 * is generated from the server's description of itself, and the routes that
 * serve a computed world are being written at the same time as this canvas. If
 * the canvas typed itself against those routes it could not be built until they
 * existed, and it would have to be rewritten every time they changed shape.
 *
 * The rule that shapes everything below: **every slot where a likelihood would
 * go is optional.** A number nobody has computed is not a zero and not a blank;
 * it is an absence, and an absence carries the reason it is absent — "no
 * market", "no engine yet", or a dash inviting the reader's own number. That is
 * the whole of the traceability rule as it reaches this layer: nothing on
 * screen may be a number nobody can account for.
 *
 * Nothing in this file, or anywhere under `src/world`, does arithmetic on a
 * likelihood. Numbers arrive from the server and are carried, unchanged and at
 * full precision, to the moment they are printed.
 */

/** What a claim is for. Its shape on the canvas carries this, never its colour. */
export type ClaimKind = "hypothesis" | "event" | "market" | "not_tradeable";

/**
 * How a push behaves when its cause goes away. `trigger` is a toppled domino —
 * it stays toppled. `sustain` is an apple on a desk — take the desk away and
 * the apple falls.
 */
export type LinkMode = "trigger" | "sustain";

/** Whose number this is. The three are never averaged into one. */
export type BeliefOwner = "model" | "user" | "market";

/**
 * A likelihood and the range around it, both at full precision.
 *
 * The range says **how sure we are of the number** — not how much the world can
 * move. How much the world can move is already inside `p`. Rounding to two
 * significant figures happens once, at the moment of display, and never here.
 */
export interface Ranged {
  /** How likely the claim is to come out true, from 0 to 1. */
  readonly p: number;
  /** The bottom of the range around `p`. Never above it. */
  readonly lo: number;
  /** The top of the range around `p`. Never below it. */
  readonly hi: number;
}

/**
 * Which of the three absences this is. It is what picks the words.
 *
 * - `no_engine` — nothing has worked this number through the map yet.
 * - `no_market` — no venue quotes this claim.
 * - `not_said` — nobody has given a number. The one dash on screen with a
 *   meaning: the reader's own empty slot, inviting a number.
 */
export type AbsenceKind = "no_engine" | "no_market" | "not_said";

/**
 * A number that is not here, and why.
 *
 * `words` is what the reader sees where the number would have been — "no
 * market", "no engine yet", or a dash. `reason` is the sentence that says why,
 * so no slot on screen is ever merely empty. `kind` is which of the three this
 * is, so that code can tell one absence from another without reading its words
 * back — the dash that invites a number is not the dash that means nothing was
 * computed.
 */
export interface Absence {
  /** Which absence this is. */
  readonly kind: AbsenceKind;
  /** What is printed where the number would be. Never blank, never a zero. */
  readonly words: string;
  /** Why there is no number, in plain words. */
  readonly reason: string;
}

/**
 * A value we may not have, with the reason standing in its place when we do not.
 *
 * `reading` is optional — every number slot in this view model is — and when it
 * is missing, `absence` is present and says why. The two halves are written as
 * a choice between two shapes so that the type itself forbids an empty slot
 * with no reason attached: there is no way to write one down.
 */
export type Known<Reading> =
  | { readonly reading: Reading; readonly absence?: undefined }
  | { readonly reading?: undefined; readonly absence: Absence };

/** One slot where a likelihood belongs. */
export type Slot = Known<Ranged>;

/** The three voices on one claim, each in its own slot, never merged. */
export interface BeliefSlots {
  /** What the model thinks. */
  readonly model: Slot;
  /** What the reader thinks. Absent until they say. */
  readonly user: Slot;
  /** What a venue is pricing. Absent when no venue quotes this claim. */
  readonly market: Slot;
}

/**
 * What kind of push an arrow carries over time.
 *
 * `impulse` is a one-time spike that fades away by its own half-life. `step`
 * switches on and holds. `ramp` climbs from nothing to full size across the
 * delay and then holds. The wire's stroke pattern says which, and it is the
 * only thing the stroke says.
 */
export type LinkShape = "impulse" | "step" | "ramp";

/**
 * Where an arrow and its number came from — a receipt our own pipeline writes,
 * never something a model says about itself.
 *
 * Seven values, drawn on the map as a mark of one, two or three dots at the
 * arrow's tail, with the exact word beside the same mark in the panel.
 */
export type Provenance =
  | "documented"
  | "historical"
  | "market_implied"
  | "argued"
  | "user"
  | "asserted"
  | "simulated";

/** One published item behind an arrow, and the day we fetched it — or that nobody did. */
export interface SourceView {
  /** Where the reader goes to check it. */
  readonly url: string;
  /** What the reader will see when they get there, in the publisher's words. */
  readonly title: string;
  /** The host name the address points at, with any leading `www.` dropped. */
  readonly host: string;
  /** The day our own retrieval step fetched it, or the reason there is no day. */
  readonly retrieved: { readonly day: string } | { readonly absence: Absence };
}

/** How often this kind of thing has happened before, when there is an honest set to count. */
export interface BaseRateView {
  /** The set of past cases being counted, stated so somebody else could recount them. */
  readonly referenceClass: string;
  /** How many cases in that set came out true. */
  readonly k: number;
  /** How many cases are in the set altogether. */
  readonly n: number;
  /** Web addresses where the count can be checked. Empty means nobody has checked it. */
  readonly sources: readonly SourceView[];
}

/** One published item for or against a claim, as the tile shows it. */
export interface EvidenceClipping {
  /** What the source says, in one sentence, in our words. */
  readonly line: string;
  /**
   * A single letter standing for the publication, taken from the host name in
   * the source's own web address — `bbc.com` gives `B`.
   *
   * A letter rather than the publication's icon, on purpose: fetching an icon
   * is a request to somebody else's server, and the packaged demo draws its
   * first frame without making one.
   */
  readonly monogram: string;
  /** The host name the monogram came from, so the letter can be accounted for. */
  readonly host: string;
  /** `1` when the item supports the claim, `-1` when it cuts against it. */
  readonly direction: 1 | -1;
  /** Where to read it, so the reader can check us. */
  readonly url: string;
}

/**
 * A word shown where a likelihood would go.
 *
 * While the reader has supposed a claim true it is true in every simulated
 * world, so there is no number to show and inventing one would answer a
 * question nobody asked. The tile shows *Supposed · Oct 1* instead. Nothing in
 * this pull request produces one — the buttons that do arrive later — but the
 * chip can already render it, and its test proves it.
 */
export interface Standing {
  /** The words, such as "Supposed · Oct 1". */
  readonly words: string;
  /** Why the claim stands this way, for the reader who asks. */
  readonly reason: string;
}

/** One claim, as a tile draws it. */
export interface ClaimView {
  /** The claim's identifier on the map. */
  readonly id: string;
  /** The claim in one sentence, as a person would say it out loud. */
  readonly claim: string;
  /** What this claim is for. Carried on the tile by its shape. */
  readonly kind: ClaimKind;
  /** The day the claim is settled by, as the server wrote it: `2026-11-01`. */
  readonly resolvesBy: string;
  /** Who or what applies the test that settles it. */
  readonly resolutionSource: string;
  /**
   * The test itself, written so that two people reading it would agree on the
   * answer. Too long for a tile; the panel beside the map prints it in full.
   */
  readonly resolutionCriteria: string;
  /**
   * The model's likelihood for this claim before its causes are taken into
   * account. Never drawn on a tile — a second number beside the model's would
   * be a fourth voice — and always drawn in the panel, where the decomposition
   * starts from it.
   */
  readonly prior: Ranged;
  /** How often this kind of thing has happened before, or the reason there is no such count. */
  readonly baseRate: { readonly reading: BaseRateView } | { readonly absence: Absence };
  /** The three likelihoods, side by side. */
  readonly beliefs: BeliefSlots;
  /** At most two published items, for and against. What the tile has room for. */
  readonly evidence: readonly EvidenceClipping[];
  /**
   * Every published item on this claim, in the order the map stores them.
   *
   * The tile shows two; the panel shows all of them, because a claim you can
   * only see half the evidence for is a claim you cannot argue with.
   */
  readonly evidenceInFull: readonly EvidenceClipping[];
  /**
   * The multiplied-out likelihood of the steps of one route from the
   * hypothesis to this claim.
   *
   * A chain of four plausible steps is not a plausible chain, and this is the
   * number that says so. It arrives **on the world**, computed by the engine.
   * Nothing in the browser multiplies anything to fill it in, and the slot holds
   * its absence until the engine can answer.
   */
  readonly pathProduct: Slot;
  /** A word shown instead of a likelihood, when the claim is standing on the reader's say-so. */
  readonly standing?: Standing;
  /**
   * What an edit did to this claim, in one word. Absent on a world with no
   * edits behind it — the base map, where nothing has been changed.
   */
  readonly diff?: DiffState;
  /**
   * What this claim's tile says about the edits behind it, in order.
   *
   * Two badges in a row read as a sequence: *Supposed · Oct 1* then *Retracted
   * · Oct 2 · by "…"*. Empty on a claim no edit touched.
   */
  readonly badges?: readonly Badge[];
  /**
   * True when this claim is **not** in the world you are looking at.
   *
   * Two worlds are laid out once, together, and painted twice in the same
   * coordinates. A claim that only one of them has is still drawn in the other,
   * faint and dashed, so that flipping between them moves nothing and every
   * difference you see is a real difference rather than a re-layout.
   */
  readonly ghost?: boolean;
}

/**
 * What an edit did to a claim.
 *
 * Four of the five are worked out from the branch alone, with no arithmetic
 * anywhere: following arrows is walking, not calculating.
 *
 * - `added` — the claim arrives in an **Add a claim** edit.
 * - `killed` — the claim is the target of a **Suppose this is false**. Forced
 *   false, full stop. "No path from the hypothesis reaches this any more" is a
 *   fact about a route, and the panel's path bar reports it in those words.
 * - `downstream` — the claim is in the affected set of at least one edit: a
 *   claim your change **can** move. Drawn live, its model number reading its
 *   absence, because nothing has worked the new number out.
 * - `untouched` — everything else. Identical to the base world, and the map can
 *   say so without hedging, because that is a proven property of an edit.
 * - `shifted` — the number moved, with a before and an after. It needs two
 *   numbers to compare, so nothing in this build ever produces one; it arrives
 *   with the engine.
 */
export type DiffState = "added" | "killed" | "downstream" | "untouched" | "shifted";

/**
 * One thing a tile says about an edit behind it — *Added*, *Supposed · Oct 1*,
 * *Retracted · Oct 2 · by "…"*.
 *
 * The words are copied from the shared vocabulary and never paraphrased, and
 * none of the six operations' code names ever appears in one.
 */
export interface Badge {
  /** The words on the badge. */
  readonly words: string;
  /** What the badge means, for the reader who asks. */
  readonly reason: string;
  /**
   * True when this badge says an earlier one no longer holds, so the tile can
   * draw the pair as a sequence with an arrow between them.
   */
  readonly overrides?: boolean;
}

/** One arrow, as a wire draws it. */
export interface LinkView {
  /** The arrow's identifier: its two ends joined, such as `H->B`. */
  readonly id: string;
  /** The claim the arrow starts at. */
  readonly source: string;
  /** The claim the arrow ends at. */
  readonly target: string;
  /** Whether the push survives its cause going away. */
  readonly mode: LinkMode;
  /**
   * How hard this arrow pushes, signed, at full precision.
   *
   * It is signed **on the claim, not on the world**. The arrow into *Brent
   * settles below $68* is `+1.6` — positive, because it makes that claim come
   * out true more often — and the thing that claim describes is a *falling*
   * price. So a push's sign is not a direction of financial effect, it never
   * takes a direction hue, and it is carried by the printed sign and a word.
   *
   * Nothing on the canvas adds one of these to anything. Choosing a stroke
   * width or a word for it is a comparison against fixed thresholds.
   */
  readonly strength: number;
  /** Days from the cause becoming true to the push reaching full size. */
  readonly lag: number;
  /** What the push does over time. The wire's stroke pattern, and nothing else. */
  readonly shape: LinkShape;
  /** Days for an `impulse` push to fall to half its size. Absent on the other two shapes. */
  readonly halfLife: number | null;
  /** The mechanism in one to three plain sentences: why this cause moves this effect. */
  readonly rationale: string;
  /** What backs the arrow, each with the day it was fetched or the reason there is none. */
  readonly sources: readonly SourceView[];
  /** Where this arrow came from. Drawn as a mark at the tail, spelled out in the panel. */
  readonly provenance: Provenance;
  /**
   * The target's likelihood with this arrow's source supposed true.
   *
   * Not computed here and not carried on the world: it costs a whole extra
   * run of the map per arrow, so the engine works one out only when a wire is
   * asked about. Until then — and always, in this build, because that route
   * does not exist yet — the slot holds its absence and the wire's chip reads
   * the push back in words instead. Never a guessed number.
   */
  readonly conditional: Slot;
  /**
   * True when this arrow is a market feeding back on the world. A feedback
   * arrow is the one arrow allowed to close a loop, and it is set aside when
   * the map is sorted into layers — otherwise there would be no left-to-right
   * order to sort it into.
   */
  readonly reflexive: boolean;
  /**
   * What an edit did to this arrow. Absent when no edit touched it.
   *
   * - `added` — an **Add a claim** edit brought it.
   * - `cut` — a supposition cut it: "take this as given, and do not tell me what
   *   caused it". It is still drawn, faint and dashed, because an arrow that
   *   simply vanished would be a change nobody could see.
   * - `retuned` — a **Change this push** edit moved its number.
   */
  readonly change?: "added" | "cut" | "retuned";
  /**
   * True when this arrow is **not** in the world you are looking at. Drawn faint
   * in the same place, so that flipping between the two worlds moves nothing.
   *
   * A ghost arrow is carried by how faint it is and by nothing else. Its stroke
   * is fully spent saying what kind of push it is — dot-dash for a spike that
   * fades, solid for a switch that holds, doubled when the push only lasts while
   * its cause does — and dashing it to say "other world" as well would leave it
   * saying neither clearly.
   */
  readonly ghost?: boolean;
}

/**
 * One world: a map with its numbers as they stand.
 *
 * "As they stand" is doing real work. In this pull request the numbers are the
 * stored example's own, read from the fixture route. When the engine's world
 * route lands they will be computed, and the slots that read as absences today
 * will fill in. Nothing here has to change for that to happen, because nothing
 * false was written.
 */
export interface WorldView {
  /** Which stored example or map this world was built from. */
  readonly baseId: string;
  /** What the map is called on screen. */
  readonly title: string;
  /**
   * The day the map is set on, as the map itself writes it: `2026-10-01`.
   *
   * Every resolve-by date on the map is a span from this day, and an edit the
   * reader makes takes effect on it, so the map reads the same whenever it is
   * opened. The browser's own clock is never consulted: a supposition dated by
   * the reader's time zone would make the same map read differently in two
   * places.
   */
  readonly today: string;
  /**
   * The branch this world has applied, when it has one.
   *
   * Absent on the base world, which is the empty branch. What the branch panel
   * lists, and what every diff state on the claims above was worked out from.
   */
  readonly branch?: BranchView;
  /** The claim the reader started from. */
  readonly hypothesisId: string;
  /** Every claim on the map. */
  readonly claims: readonly ClaimView[];
  /** Every arrow on the map. */
  readonly links: readonly LinkView[];
  /**
   * How many versions of the map the engine ran to produce these numbers.
   *
   * Absent when nothing was computed — which is every world in this build,
   * because the engine's route does not exist yet. It is the one thing that
   * tells a belief chip whether its range was *computed* across many versions
   * of the map or merely *stated* by whoever wrote the number down, and the
   * chip says a different sentence for each. Nothing else reads it.
   */
  readonly versions?: number;

  /**
   * Where these numbers came from, in one sentence a reader can check.
   *
   * It is printed under the map. A world whose numbers cannot say where they
   * came from is exactly the state this product refuses to show.
   */
  readonly origin: string;
}

/** Which world to read: a base map, optionally with a branch applied. */
export interface WorldRequest {
  /** The stored example or map to read. */
  readonly baseId: string;
  /** The branch to apply. Left out, this is the base world. */
  readonly branchId?: string;
}

/* ---- Editing the map: branches, and the six operations ------------------- */

/**
 * One arrow an **Add a claim** edit brings with it.
 *
 * Only the two ends, because that is all working out what an edit can reach
 * needs. When the map itself supplied the arrow — as the stored example's own
 * branch does — the whole arrow is on the branch's `links` as well, and that is
 * what gets drawn.
 */
export interface AddedArrow {
  /** The arrow's identifier. */
  readonly id: string;
  /** The claim the arrow starts at. */
  readonly source: string;
  /** The claim the arrow ends at. */
  readonly target: string;
}

/**
 * One edit in a branch.
 *
 * The six operations keep their code names — `do`, `observe`, `insert`,
 * `retune`, `refine`, `believe` — **in code, in the wire format and in the
 * spec, and nowhere on screen.** What the reader sees is the button they
 * pressed and the badge it earns, both copied word for word from the shared
 * vocabulary. `frontend/src/components/BranchPanel.tsx` is the one place those
 * words are written.
 */
export type Edit =
  /** Take this as given, and do not tell me what caused it. */
  | {
      readonly op: "do";
      /** The claim being supposed true or false. */
      readonly target: string;
      /** True to suppose it holds, false to suppose it does not. */
      readonly value: boolean;
      /** The day the supposition takes effect, as the map writes a day. */
      readonly at: string;
    }
  /** This is news — update what came before it too. */
  | {
      readonly op: "observe";
      readonly target: string;
      readonly value: boolean;
      readonly at: string;
    }
  /** A claim and its arrows arrive together. */
  | {
      readonly op: "insert";
      /** The new claim's identifier on the map. */
      readonly claimId: string;
      /** The new claim in its own words, which is what the badge quotes. */
      readonly words: string;
      /** The arrows that attach it. */
      readonly arrows: readonly AddedArrow[];
    }
  /** One number on one arrow moves. */
  | {
      readonly op: "retune";
      /** The arrow whose push is being changed. */
      readonly link: string;
      /** The new push, signed, on the same scale the arrow carries. */
      readonly strength: number;
      /** What the push was before, so the panel can read the change back. */
      readonly wasStrength: number;
    }
  /** The finer claims add back up to the one they replace. Not built yet. */
  | { readonly op: "refine"; readonly target: string }
  /** The reader's own likelihood, beside the model's and the market's. */
  | { readonly op: "believe"; readonly target: string; readonly belief: Ranged };

/** The four hues a branch may take. Never amber: amber means "the money moves down". */
export type BranchHue = "violet" | "teal" | "rose" | "slate";

/**
 * A named, ordered list of edits over a base map. A branch *is* the edits.
 *
 * It holds no likelihoods and no results. `claims` and `links` are the drawable
 * detail for what an **Add a claim** edit brought with it, when the map
 * supplied a whole claim rather than only its words — the stored example's own
 * branch does; a claim the reader types does not, and is shown in the branch
 * panel rather than drawn as a tile.
 */
export interface BranchView {
  /** This branch's identifier. */
  readonly id: string;
  /** The name the reader reads. */
  readonly label: string;
  /** Which of the four hues its lane and its name chip take. */
  readonly hue: BranchHue;
  /** The edits, in the order they were made. Appended to, never rewritten. */
  readonly edits: readonly Edit[];
  /** Whole claims an edit added, when the map supplied them. */
  readonly claims: readonly ClaimView[];
  /** Whole arrows an edit added, when the map supplied them. */
  readonly links: readonly LinkView[];
}

/**
 * One ending the edit can reach, as the rail beside the map lists it.
 *
 * Every number on a row is optional, and before the engine every one of them is
 * an absence with its reason. The rail ranks nothing and computes nothing.
 */
export interface DeltaRow {
  /** The ending's identifier on the map. */
  readonly claimId: string;
  /** The ending in its own words. */
  readonly label: string;
  /** What kind of ending it is, which is what says whether anything trades. */
  readonly kind: ClaimKind;
  /** How far the number moved, and the day it moved furthest. */
  readonly move: Known<{ readonly from: number; readonly to: number; readonly largestOn: string }>;
  /** How firm: the width of this world's own range on the claim. */
  readonly rangeWidth: Known<number>;
  /** Same direction: the share of versions of the map that moved the same way. */
  readonly agreement: Known<number>;
}

/**
 * What the panel beside the map is open on, and what the map draws a ring
 * around. One name for one thing: the map, the panel and the keyboard all mean
 * the same shape by it.
 */
export type Selection =
  | { readonly kind: "claim"; readonly id: string }
  | { readonly kind: "wire"; readonly id: string }
  | null;

