/**
 * Working out where every tile goes, on a thread that is not the one drawing
 * the page.
 *
 * Laying out a map of sixty tiles takes the layout engine somewhere between
 * fifty and a hundred and fifty milliseconds. On the thread that draws the page
 * that is three to nine dropped frames: the page freezes, the map stutters as it
 * grows, and a tool that stutters reads as a tool that is struggling. So the
 * work happens on a background thread, and the page carries on drawing while it
 * waits.
 *
 * The background thread is the layout engine's own. Its package ships the
 * algorithm as a script written to be run that way — ask it for a copy of that
 * script's address and hand the address over, and it starts the thread itself.
 * Writing our own wrapper thread around it, which was the first attempt, does
 * not work: the script checks whether it is already inside a background thread
 * and, finding that it is, wires itself up as that thread rather than handing
 * back something to call.
 *
 * Nothing on this thread ever sees a likelihood. A tile, to the layout engine,
 * is an identifier and a box.
 */

import ELK, { type ELK as LayoutEngine } from "elkjs/lib/elk-api.js";
import elkWorkerAddress from "elkjs/lib/elk-worker.min.js?url";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  type LayoutEdge,
  type LayoutTile,
  type Position,
  readPositions,
  toElkGraph,
} from "./elkGraph";

/** Where every tile sits, and which run of the layout put it there. */
export interface Layout {
  /** Where each tile sits, by identifier. Empty until the first answer arrives. */
  readonly positions: ReadonlyMap<string, Position>;
  /**
   * How many layouts have finished.
   *
   * Zero means none has, and so nothing should be drawn yet. It goes up by one
   * each time, which is what lets the canvas tell "the map has just been laid
   * out for the first time" — frame the whole map — from "it has been laid out
   * again" — stay where the reader was.
   */
  readonly runs: number;
  /**
   * Which map these positions are for.
   *
   * It lags the map on screen by exactly as long as the layout takes, and that
   * matters: framing the view from positions worked out for the map *before* the
   * branch would frame the wrong thing, and then the right thing would arrive
   * underneath it.
   */
  readonly laidOutFor: string;
  /** What went wrong, in a sentence, if anything did. */
  readonly failure: string | null;
}

/**
 * One background thread, shared by everything on the page that needs a layout.
 *
 * Started the first time it is asked for rather than when this file loads,
 * because a test running in a simulated page has no threads to start and should
 * not have one started for it.
 */
let engine: LayoutEngine | null = null;

function layoutEngine(): LayoutEngine {
  engine ??= new ELK({ workerUrl: elkWorkerAddress });
  return engine;
}

/**
 * How long the background thread gets before the page does the work itself.
 *
 * The background thread is the normal path and it answers in well under a tenth
 * of a second. But a thread that never answers leaves every tile stacked in the
 * top left corner with nothing on screen saying why — which is the "why did it
 * do that" failure in its purest form. Some browsers, and some browsers under
 * instrumentation, will not run the layout engine's own worker script at all.
 *
 * So after this long the page lays the map out on its own thread instead. That
 * costs a few dropped frames once; a map that never arrives costs everything.
 */
const THREAD_PATIENCE = 2000;

/** What the race below hands back when the background thread has not answered. */
const TOO_SLOW = Symbol("the background thread has not answered");

/**
 * Lay the map out on the background thread, or — if that thread does not answer
 * — on this one.
 *
 * The fallback is loaded only if it is needed, so the packaged app does not
 * carry a second copy of the layout engine unless a reader's browser makes it
 * necessary.
 */
async function laidOut(graph: Parameters<LayoutEngine["layout"]>[0]) {
  const answer = await Promise.race([
    layoutEngine().layout(graph),
    new Promise<typeof TOO_SLOW>((settle) => {
      setTimeout(() => settle(TOO_SLOW), THREAD_PATIENCE);
    }),
  ]);
  if (answer !== TOO_SLOW) {
    return answer;
  }
  const onThisThread = await import("elkjs/lib/elk.bundled.js");
  return new onThisThread.default().layout(graph);
}

/** Say what went wrong in a sentence, whatever was thrown. */
function inWords(reason: unknown): string {
  return reason instanceof Error ? reason.message : "The layout engine stopped without saying why.";
}

/**
 * Work out where every tile goes, on a background thread, and keep tiles that
 * have already been placed exactly where they are.
 *
 * @param tiles Every tile to place, with its height, in reading order.
 * @param edges Every arrow that gets a say in the left-to-right order. Feedback
 *   arrows are left out by the caller.
 * @param mapKey Which map this is. Pinning is for a map that **grows** — a tile
 *   arriving must never shove the tiles already on screen. A different map is a
 *   different question: opening a branch that adds a claim before the hypothesis
 *   moves every column one step right, and it has to, because a cause cannot be
 *   drawn to the right of what it causes. So when this changes, the pins go and
 *   the whole thing is laid out again, once, over the union of both worlds.
 */
export function useLayout(
  tiles: readonly LayoutTile[],
  edges: readonly LayoutEdge[],
  mapKey: string,
): Layout {
  // The map only changes when the claims or the arrows do, and comparing two
  // lists of strings is cheaper and steadier than comparing two arrays by
  // identity — a fresh array with the same contents must not start a re-layout.
  const shape = useMemo(
    () =>
      JSON.stringify([
        tiles.map((tile) => [tile.id, tile.height]),
        edges.map((edge) => [edge.id, edge.source, edge.target]),
      ]),
    [tiles, edges],
  );

  // Where tiles already sit. Held across runs, because that is what pinning
  // means: this is the memory that stops a late arrival moving an early one.
  const placed = useRef(new Map<string, Position>());
  const laidOutFor = useRef(mapKey);
  const [layout, setLayout] = useState<Layout>({
    positions: new Map(),
    runs: 0,
    laidOutFor: "",
    failure: null,
  });

  useEffect(() => {
    let stillWanted = true;
    if (laidOutFor.current !== mapKey) {
      // A different map. Nothing is pinned, because the columns themselves have
      // moved: the union of two worlds is laid out once, together, and then
      // painted twice in those same coordinates.
      placed.current = new Map();
      laidOutFor.current = mapKey;
    }
    const [boxes, wires] = JSON.parse(shape) as [[string, number][], [string, string, string][]];
    const graph = toElkGraph(
      boxes.map(([id, height]) => ({ id, height })),
      wires.map(([id, source, target]) => ({ id, source, target })),
      placed.current,
    );
    laidOut(graph).then(
      (laidOut) => {
        if (!stillWanted) {
          return;
        }
        const positions = readPositions(laidOut, placed.current);
        placed.current = positions;
        setLayout((was) => ({
          positions,
          runs: was.runs + 1,
          laidOutFor: mapKey,
          failure: null,
        }));
      },
      (reason: unknown) => {
        if (stillWanted) {
          setLayout((was) => ({ ...was, failure: inWords(reason) }));
        }
      },
    );
    return () => {
      stillWanted = false;
    };
  }, [shape, mapKey]);

  return layout;
}

/**
 * The first screen: what you can start from, and the two ways in.
 *
 * No illustration and no empty box staring back. The four examples from the
 * brief are on the page as cards, the two doors are named and explained in a
 * line each, and one card opens a map right now.
 *
 * **The three cards that do not open anything say so.** Turning a sentence you
 * typed into a map needs the model, and that half is not built yet — so those
 * three carry the words *not yet live* and the reason underneath, read from the
 * server's own answer about whether it is ready. A card that quietly did
 * nothing when clicked would be the worse choice by a distance: the reader
 * would think the tool was broken rather than unfinished.
 */

import type { FixtureSummary } from "../api/client";
import "./launchpad.css";

/** One of the two ways into the tool. */
interface Door {
  readonly name: string;
  readonly line: string;
}

/**
 * The two doors, from the requirements: start from an event and follow it out,
 * or name where you think it ends and ask whether the chain really gets there.
 */
const DOORS: readonly Door[] = [
  {
    name: "Explore",
    line: "Start from an event and see what it would cause, out to the things you could trade.",
  },
  {
    name: "Verify",
    line: "Name where you think it ends, and see whether a chain really gets there — or that none does.",
  },
];

/**
 * The three examples from the brief that need the model.
 *
 * They are what a reader would type, written out so the shape of the input is
 * obvious before anyone has typed anything.
 */
const WAITING_EXAMPLES: readonly string[] = [
  "Republicans win the House but Democrats take the Senate during the midterms.",
  "Models more capable than Fable get export restricted by the United States.",
  "Photonic chips get adopted faster than expected.",
];

/** What the launchpad needs to draw itself. */
export interface LaunchpadProps {
  /**
   * The stored examples the server ships with, or null while the answer is
   * still on its way.
   */
  readonly examples: readonly FixtureSummary[] | null;
  /** Why the list could not be read, if it could not be. */
  readonly failure: string | null;
  /**
   * Why the other three cards are not live, in one sentence, worked out from
   * what the server said about itself.
   */
  readonly notLiveReason: string;
  /** Open a stored example's map. */
  readonly onOpen: (id: string) => void;
}

/** The first screen. */
export function Launchpad({ examples, failure, notLiveReason, onOpen }: LaunchpadProps) {
  return (
    <div className="launchpad">
      <section aria-labelledby="doors-heading">
        <h2 className="section-heading" id="doors-heading">
          Two ways in
        </h2>
        <ul className="doors">
          {DOORS.map((door) => (
            <li className="door" key={door.name}>
              <span className="door__name">{door.name}</span>
              <span className="door__line">{door.line}</span>
            </li>
          ))}
        </ul>
      </section>

      <section aria-labelledby="examples-heading">
        <h2 className="section-heading" id="examples-heading">
          Start from one of these
        </h2>
        <ul className="examples">
          {examples === null ? (
            <li className="example example--waiting">
              <span className="example__claim">
                {failure ?? "Asking the server which examples it ships with."}
              </span>
              {failure === null ? <span className="placeholder" aria-hidden="true" /> : null}
            </li>
          ) : (
            examples.map((example) => (
              <li key={example.id}>
                <button
                  className="example example--live"
                  type="button"
                  onClick={() => onOpen(example.id)}
                >
                  <span className="example__claim">{example.title}</span>
                  <span className="example__line">{example.one_line}</span>
                  <span className="example__action">Open the map</span>
                </button>
              </li>
            ))
          )}

          {WAITING_EXAMPLES.map((claim) => (
            <li className="example example--waiting" key={claim}>
              <span className="example__claim">{claim}</span>
              <span className="example__line">
                Would be turned into a map of what it causes, ending in trades.
              </span>
              <span className="example__action example__action--waiting">
                <span className="example__badge">not yet live</span>
                {notLiveReason}
              </span>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

/**
 * How the map is handed to the automatic layout engine, and how its answer is
 * read back.
 *
 * Everything here is a plain function over plain data: no browser, no worker,
 * no React. That is on purpose — it is the part worth testing, and it is
 * testable without starting anything.
 *
 * The layout engine is ELK, which sorts a map into left-to-right layers and
 * places the tiles in each layer so that as few arrows cross as possible. It is
 * slow enough on a large map to be worth keeping off the thread that draws the
 * page, which is what `layoutRunner.ts` does with the functions below.
 */

import type { ElkExtendedEdge, ElkNode, LayoutOptions } from "elkjs/lib/elk-api";
import { TILE_WIDTH } from "./geometry";

/** Where a tile sits, in the map's own coordinates. */
export interface Position {
  readonly x: number;
  readonly y: number;
}

/**
 * One tile, reduced to the two things the layout engine needs: what it is
 * called and how tall it is.
 *
 * The height comes from the claim's own content — see `geometry.ts` — rather
 * than from measuring a tile the browser has drawn. That is what keeps the
 * layout a plain function of the map, testable without a browser, and it is why
 * a tile's box and the box the layout reserved for it are always the same box.
 */
export interface LayoutTile {
  readonly id: string;
  readonly height: number;
}

/** One arrow, reduced to the two things the layout engine needs. */
export interface LayoutEdge {
  readonly id: string;
  readonly source: string;
  readonly target: string;
}

/**
 * The layout settings, written out in one place so the picture can be argued
 * with rather than guessed at.
 *
 * - **layered** — claims are sorted into columns and arrows travel between
 *   them. This is what makes the map readable left to right instead of a ball
 *   of string.
 * - **RIGHT** — causes on the left, effects on the right, which is the order an
 *   English sentence puts them in.
 * - **NETWORK_SIMPLEX** — how tiles are placed up and down within a column. It
 *   pulls each tile level with the tiles it is joined to, so an arrow is
 *   horizontal wherever it can be.
 * - **semiInteractive** — when a tile already has a position, keep its place in
 *   the order of its column rather than sorting it afresh. This is what stops
 *   the map rearranging itself as it grows.
 * - **120 between layers** — the gap between columns, which is also the length
 *   of the shortest wire, and so how much room a wire has to say something.
 * - **48 within a layer** — the gap between two tiles in the same column. Not
 *   settled anywhere; chosen so the note a tile opens when you look at a belief
 *   chip has somewhere to go.
 */
export const LAYOUT_OPTIONS: LayoutOptions = {
  "elk.algorithm": "layered",
  "elk.direction": "RIGHT",
  "elk.layered.nodePlacement.strategy": "NETWORK_SIMPLEX",
  "elk.layered.crossingMinimization.semiInteractive": "true",
  "elk.layered.spacing.nodeNodeBetweenLayers": "120",
  "elk.spacing.nodeNode": "48",
};

/**
 * Build the map the layout engine is asked to lay out.
 *
 * Tiles that already have a position are handed back with it, as a hint that
 * says "this one is already somewhere; work around it". That, together with the
 * semi-interactive setting above, is what keeps a tile arriving late from
 * shuffling the tiles that arrived before it.
 *
 * @param tiles Every tile to place, with its height, in reading order.
 * @param edges Every arrow between them. Feedback arrows are left out by the
 *   caller: an arrow that points backwards has no say in a left-to-right order.
 * @param placed Where tiles already sit, for the ones that have been placed.
 */
export function toElkGraph(
  tiles: readonly LayoutTile[],
  edges: readonly LayoutEdge[],
  placed: ReadonlyMap<string, Position>,
): ElkNode {
  const children: ElkNode[] = tiles.map(({ id, height }) => {
    const already = placed.get(id);
    const child: ElkNode = { id, width: TILE_WIDTH, height };
    if (already !== undefined) {
      return {
        ...child,
        x: already.x,
        y: already.y,
        layoutOptions: { "elk.position": `(${already.x},${already.y})` },
      };
    }
    return child;
  });

  const wires: ElkExtendedEdge[] = edges.map((edge) => ({
    id: edge.id,
    sources: [edge.source],
    targets: [edge.target],
  }));

  return { id: "map", layoutOptions: LAYOUT_OPTIONS, children, edges: wires };
}

/**
 * Read the layout engine's answer back, keeping every tile that was already
 * placed exactly where it was.
 *
 * The hint above asks the engine to leave placed tiles alone, and it mostly
 * does — but "mostly" is not a promise, and losing your place because a new
 * tile arrived is the thing this is here to prevent. So the rule is made
 * absolute on our side: **a tile that had a position keeps that position, to
 * the pixel, and only a tile that had none takes a new one.**
 *
 * @param laidOut What the layout engine returned.
 * @param placed Where tiles already sat before it ran.
 * @returns Where every tile sits now.
 */
export function readPositions(
  laidOut: ElkNode,
  placed: ReadonlyMap<string, Position>,
): Map<string, Position> {
  const positions = new Map<string, Position>();
  for (const child of laidOut.children ?? []) {
    const pinned = placed.get(child.id);
    if (pinned !== undefined) {
      positions.set(child.id, pinned);
      continue;
    }
    positions.set(child.id, { x: child.x ?? 0, y: child.y ?? 0 });
  }
  return positions;
}

